fn fit_rect_into(target: Rectangle, src_width: f32, src_height: f32) -> Rectangle {
    let target_ratio = target.width / target.height;
    let src_ratio = src_width / src_height;
    if src_ratio > target_ratio {
        let width = target.width;
        let height = width / src_ratio;
        let y = target.y + (target.height - height) / 2.0;
        Rectangle::new(target.x, y, width, height)
    } else {
        let height = target.height;
        let width = height * src_ratio;
        let x = target.x + (target.width - width) / 2.0;
        Rectangle::new(x, target.y, width, height)
