pub fn decl_module_indented<W: std::io::Write>(
    w: &mut W,
    env: &mut Env,
    mod_name: &'static str,
    indent: usize,
    block: impl FnOnce(&mut Env),
) {
    write!(w, "{}", format_args!("{: >1$}", "", indent * env.nested())).unwrap();
    let module_declaration = env.new_module(mod_name);
