use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Serialize, Deserialize, Clone)]
struct TimestampedPayload<T> {
    timestamp: u128,
    inner: T,
}

pub fn event_with_timestamp<T>(name: impl ToString, payload: &T) -> Event
where
    T: Serialize + Clone,
{
    let wrapper = TimestampedPayload {
        timestamp: SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_millis() as u128,
        inner: payload.clone(),
    };
    Event::with_payload(name, &wrapper)
}",
