{
  "title": "Rewrite delayed receipts for a new shard layout",
  "description": "When the forked network changes its shard layout, delayed receipts must be moved from their original shards to the shards that will receive them after account IDs are remapped. This helper iterates over all tracked receipts, reads each receipt, re‑maps the receiver account, and writes the receipt to the correct target shard while removing it from the source shard.",
  "code_context": "use crate::delayed_receipts::DelayedReceiptTracker;
use crate::storage_mutator::ShardUpdateState;
use near_primitives::shard_layout::{ShardLayout, ShardUId};
use near_primitives::types::{StateRoot, PublicKey};
use near_store::{ShardTries, Trie};
use near_primitives::receipt::Receipt;
use near_primitives::trie_key::TrieKey;
use near_primitives::receipt::ReceiptOrStateStoredReceipt;
use near_primitives::trie_key::TrieQueueIndices;
use near_mirror::key_mapping::map_account;
use anyhow::Context;
use std::collections::HashMap;
use std::collections::BTreeSet;
use borsh::BorshSerialize;

fn remove_source_receipt_index(
    updates: &mut [HashMap<u64, Option<Vec<u8>>>],
    source_shard_uid: ShardUId,
    target_shard_layout: &ShardLayout,
    index: u64,
) {
    if !target_shard_layout.shard_uids().any(|s| s == source_shard_uid) {
        return;
    }
    let shard_idx = target_shard_layout.get_shard_index(source_shard_uid.shard_id()).unwrap();
    updates[shard_idx].entry(index).or_insert(None);
}

fn read_delayed_receipt(
    trie: &Trie,
    source_shard_uid: ShardUId,
    index: u64,
) -> anyhow::Result<Option<Receipt>> {
    let key = TrieKey::DelayedReceipt { index };
    let value = near_store::get_pure::<ReceiptOrStateStoredReceipt>(trie, &key)?;
    Ok(value.map(|r| r.into_receipt()))
}

fn set_target_delayed_receipt(
    updates: &mut HashMap<u64, Option<Vec<u8>>>,
    next_index: &mut u64,
    mut receipt: Receipt,
    default_key: &PublicKey,
) {
    near_mirror::genesis::map_receipt(&mut receipt, None, default_key);
    let value = ReceiptOrStateStoredReceipt::Receipt(std::borrow::Cow::Owned(receipt));
    let bytes = borsh::to_vec(&value).unwrap();
    updates.insert(*next_index, Some(bytes));
    *next_index += 1;
}",
  "function_signature": "fn rewrite_delayed_receipts(
    trackers: Vec<DelayedReceiptTracker>,
    shard_tries: &ShardTries,
    source_state_roots: &HashMap<ShardUId, StateRoot>,
    target_shard_layout: &ShardLayout,
    default_key: &PublicKey,
) -> anyhow::Result<()>"
}

