            let d_bytes = self.pow_distance.as_ref().ok_or(sigma_ser::ScorexSerializationError::Misc("pow_distance must be == Some(_) for autolykos v1"))?.to_signed_bytes_be();
            w.put_u8(d_bytes.len() as u8)?;
            w.write_all(&d_bytes)?;
        } else {
            self.miner_pk.scorex_serialize(w)?;
            w.write_all(&self.nonce)?;
        }
        Ok(())
    }
