pub fn generate_merkle_proof(member: &str, tree: &MerkleTree<SortingSha256Hasher>) -> Vec<String> {
    let leaf_hash = Sha256::hash(member.as_bytes());
    let leaves = tree.leaves();
    let mut index_opt = None;
    for (i, leaf) in leaves.iter().enumerate() {
        if leaf == &leaf_hash {
            index_opt = Some(i);
            break;
        }
    }
    let index = match index_opt {
        Some(i) => i,
        None => return vec![],
    };
    let proof = tree.proof(&[index]);
    proof.proof_hashes_hex()
